-- A record's position is the record's own.
-- Persons, institutions and events used to inherit a position from a linked
-- place, which made everyone associated with one named place share that
-- place's single point. Linking is association, not assignment: each record
-- now carries its own latitude and longitude, recorded and maintained
-- independently of any place it is associated with. The provenance columns
-- mirror place (a coordinate is only as good as the way it was obtained).
ALTER TABLE person ADD COLUMN latitude REAL CHECK (latitude IS NULL OR (latitude BETWEEN -90 AND 90));
ALTER TABLE person ADD COLUMN longitude REAL CHECK (longitude IS NULL OR (longitude BETWEEN -180 AND 180));
ALTER TABLE person ADD COLUMN geo_precision TEXT;
ALTER TABLE person ADD COLUMN geocoding_method TEXT;
ALTER TABLE person ADD COLUMN geo_uncertainty_m REAL;
ALTER TABLE person ADD COLUMN geometry_source TEXT;
ALTER TABLE institution ADD COLUMN latitude REAL CHECK (latitude IS NULL OR (latitude BETWEEN -90 AND 90));
ALTER TABLE institution ADD COLUMN longitude REAL CHECK (longitude IS NULL OR (longitude BETWEEN -180 AND 180));
ALTER TABLE institution ADD COLUMN geo_precision TEXT;
ALTER TABLE institution ADD COLUMN geocoding_method TEXT;
ALTER TABLE institution ADD COLUMN geo_uncertainty_m REAL;
ALTER TABLE institution ADD COLUMN geometry_source TEXT;
ALTER TABLE event ADD COLUMN latitude REAL CHECK (latitude IS NULL OR (latitude BETWEEN -90 AND 90));
ALTER TABLE event ADD COLUMN longitude REAL CHECK (longitude IS NULL OR (longitude BETWEEN -180 AND 180));
ALTER TABLE event ADD COLUMN geo_precision TEXT;
ALTER TABLE event ADD COLUMN geocoding_method TEXT;
ALTER TABLE event ADD COLUMN geo_uncertainty_m REAL;
ALTER TABLE event ADD COLUMN geometry_source TEXT;
-- Backfill: an earlier version stored a record's precise point as a synthetic
-- place named exactly like the coordinates it carried (five decimals, comma
-- space) and linked the record to it. Those points belong to the record, so
-- they move onto the record's own columns here. The named place link returns
-- to the synthetic place's parent when there is one.
UPDATE person SET
  latitude = (SELECT CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL) FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
  longitude = (SELECT CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL) FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
  geo_precision = COALESCE(geo_precision, 'exact'),
  geocoding_method = COALESCE(geocoding_method, (SELECT p2.geocoding_method FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2))),
  geometry_source = COALESCE(geometry_source, (SELECT p2.geometry_source FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)))
WHERE latitude IS NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
UPDATE institution SET
  latitude = (SELECT CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL) FROM place p2 WHERE p2.id = institution.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
  longitude = (SELECT CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL) FROM place p2 WHERE p2.id = institution.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
