  geometry_source = COALESCE(geometry_source, (SELECT p2.geometry_source FROM place p2 WHERE p2.id = institution.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)))
WHERE latitude IS NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = institution.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
UPDATE event SET
  latitude = (SELECT CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL) FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
  longitude = (SELECT CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL) FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)),
  geo_precision = COALESCE(geo_precision, 'exact'),
  geocoding_method = COALESCE(geocoding_method, (SELECT p2.geocoding_method FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2))),
  geometry_source = COALESCE(geometry_source, (SELECT p2.geometry_source FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2)))
WHERE latitude IS NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
-- The named place link returns to the synthetic place's parent where there is
-- one (the synthetic point never was the person's birthplace).
UPDATE person SET birthplace_id = (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = person.birthplace_id) WHERE birthplace_id IS NOT NULL AND (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = person.birthplace_id) IS NOT NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = person.birthplace_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
UPDATE institution SET place_id = (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = institution.place_id) WHERE place_id IS NOT NULL AND (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = institution.place_id) IS NOT NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = institution.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
UPDATE event SET place_id = (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = event.place_id) WHERE place_id IS NOT NULL AND (SELECT p2.parent_place_id FROM place p2 WHERE p2.id = event.place_id) IS NOT NULL AND EXISTS (SELECT 1 FROM place p2 WHERE p2.id = event.place_id AND p2.name_en = p2.name_ar AND INSTR(p2.name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AS REAL)) = SUBSTR(p2.name_en, 1, INSTR(p2.name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2) AS REAL)) = SUBSTR(p2.name_en, INSTR(p2.name_en, ', ') + 2));
-- Synthetic point-places nothing references any more are closed quietly.
UPDATE place SET deleted_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
WHERE deleted_at IS NULL AND name_en = name_ar AND INSTR(name_en, ', ') > 1 AND printf('%.5f', CAST(SUBSTR(name_en, 1, INSTR(name_en, ', ') - 1) AS REAL)) = SUBSTR(name_en, 1, INSTR(name_en, ', ') - 1) AND printf('%.5f', CAST(SUBSTR(name_en, INSTR(name_en, ', ') + 2) AS REAL)) = SUBSTR(name_en, INSTR(name_en, ', ') + 2) AND NOT EXISTS (SELECT 1 FROM person p WHERE p.birthplace_id = place.id) AND NOT EXISTS (SELECT 1 FROM institution i WHERE i.place_id = place.id) AND NOT EXISTS (SELECT 1 FROM event e WHERE e.place_id = place.id) AND NOT EXISTS (SELECT 1 FROM place c WHERE c.parent_place_id = place.id) AND NOT EXISTS (SELECT 1 FROM relationship r WHERE (r.entity1_type = 'place' AND r.entity1_id = place.id) OR (r.entity2_type = 'place' AND r.entity2_id = place.id));
